// Public calendar data is cached separately from editorial content and news imports.
const calendarMemory=new Map();
function calendarText(html){return articleText(String(html)).replace(/\n+/g,' ').replace(/\s+/g,' ').trim()}
function parseCalendar(date,widget,page){
 if(!String(widget.presentations||'').includes('/days/'+date))throw new Error('Источник вернул другую дату');
 const saints=[...widget.presentations.matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)].map(m=>calendarText(m[1])).filter(Boolean).slice(0,60);
 const dayText=page.match(/<div\b[^>]*class="text day__text"[^>]*>\s*<p>([\s\S]*?)<\/p>/i)?.[1];
 const fasting=dayText?calendarText(dayText):'';
 const oldStyle=calendarText(page.match(/<div class="oldstyle">([\s\S]*?)<\/div>/)?.[1]||'').replace(/^Старый стиль\s*/, '');
 const readingBlock=page.match(/<div id="chteniya"[\s\S]*?<div class="readings-text">([\s\S]*?)<div class="scripture-sub">/i)?.[1]||'';
 const readings=articleText(readingBlock).split(/\n\n/).filter(Boolean).join('\n\n');
 if(!saints.length||!fasting||!readings||readings.length>15000)throw new Error('Неполные данные календаря');
 return {date,oldStyle,fasting,saints,readings,source:'https://azbyka.ru/days/'+date,readingsUrl:'https://azbyka.ru/biblia/days/'+date,updatedAt:now()};
}
async function calendarFetch(url){
 const r=await fetch(url,{redirect:'manual',signal:AbortSignal.timeout(10000),headers:{Accept:'application/json,text/html','User-Agent':'PreobrazhenskoePortal/1.0'}});
 if(!r.ok)throw new Error('Календарь: HTTP '+r.status);
 const reader=r.body.getReader(),parts=[];let size=0;
 while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>1500000){await reader.cancel();throw new Error('Календарь: превышен объём ответа')}parts.push(value)}
 const out=new Uint8Array(size);let offset=0;for(const p of parts){out.set(p,offset);offset+=p.length}return new TextDecoder().decode(out);
}
async function calendarApi(req,env){
 if(req.method!=='GET')return new Response('Method not allowed',{status:405,headers:{Allow:'GET'}});
 const date=today(),key='public-calendar-v1/'+date+'.json';
 let item=calendarMemory.get(date);if(item&&item.until>Date.now())return json(await item.promise);
 const promise=(async()=>{
  const cached=await env.BUCKET.get(key);if(cached){const data=await cached.json();if(data.date===date&&data.saints?.length&&data.readings&&data.fasting)return data}
  const [widget,page]=await Promise.all([calendarFetch('https://azbyka.ru/days/widgets/presentations.json?date='+date),calendarFetch('https://azbyka.ru/days/'+date)]);
  const data=parseCalendar(date,JSON.parse(widget),page);
  await env.BUCKET.put(key,JSON.stringify(data),{httpMetadata:{contentType:'application/json'}});return data;
 })();
 calendarMemory.clear();calendarMemory.set(date,{promise,until:Date.now()+300000});
 try{return json(await promise)}catch(error){calendarMemory.delete(date);console.warn('Orthodox calendar unavailable: '+String(error.message).slice(0,250));return json({date,error:'Календарь временно недоступен',source:'https://azbyka.ru/days/'+date},503)}
}
function calendarStrip(){const date=today();return `<aside class="calendar-strip" aria-label="Православный календарь"><details id="orthodox-calendar"><summary><span class="calendar-heading">Православный календарь</span><time id="calendar-date" datetime="${date}">${esc(dateLabel(date))}</time><span id="calendar-fast" class="calendar-fast">День, пост, память святых и чтения</span><span class="calendar-expand">Подробнее</span></summary><div class="calendar-content" tabindex="0" role="region" aria-label="Память святых и чтения дня"><p id="calendar-status" role="status">Загружаем календарь…</p><div id="calendar-data" hidden><div class="calendar-columns"><div><h3>Память святых и праздники</h3><ul id="calendar-saints"></ul></div><div><h3>Чтения Священного Писания</h3><div id="calendar-readings"></div><p><a id="calendar-readings-link" class="text-link" href="https://azbyka.ru/biblia/days/${date}" target="_blank" rel="noopener noreferrer">Читать тексты чтений ↗</a></p></div></div></div><p class="small"><a id="calendar-source" class="text-link" href="https://azbyka.ru/days/${date}" target="_blank" rel="noopener noreferrer">Календарь «Азбуки веры» ↗</a> · Время Новосибирска</p><noscript><p>Откройте календарь по ссылке выше, чтобы узнать пост, память святых и чтения.</p></noscript></div></details></aside>`}
function calendarFeastLevel(text){
 const t=String(text).toLowerCase().replace(/ё/g,'е');
 if(/рождество (господа|христово)|крещение господ|богоявление|сретение господ|благовещение|вход господ.*иерусалим|вознесение господ|(?:день )?святой троицы|пятидесятница|преображение господ|успение.*богородиц|рождество.*богородиц|воздвижение.*крест|введение.*храм.*богородиц/.test(t))return 'twelve';
 if(/покров.*богородиц|обрезание господ|рождество.*иоанна.*предтеч|(?:первоверховных|первоверховные).*петра.*павла|усекновение.*главы.*иоанна/.test(t))return 'great';
 if(/светлое христово воскресение|пасха/.test(t))return 'pascha';
 return '';
}
function extractDayReadings(text){
 const readings=[];
 for(const paragraph of String(text||'').replace(/\u0301/g,'').split(/\n\s*\n/)){
  const pattern=/(?<![\p{L}\p{N}])((?:[123]\s*)?(?:Кор|Фес|Сол|Тим|Пет|Ин)|Деян|Рим|Гал|Еф|Флп|Фил|Кол|Тит|Флм|Евр|Иак|Иуд|Мф|Мк|Лк)\.\s*(\d+\s*:\s*\d+(?:\s*[–—−\-,:;]\s*\d+)*)(?:\s*\(зач\.\s*\d+\))?/gu;
  for(const match of paragraph.matchAll(pattern)){
   const book=match[1].replace(/\s+/g,''),gospel=['Мф','Мк','Лк','Ин'].includes(book),prefix=paragraph.slice(0,match.index),contexts=[...prefix.matchAll(/(?:Утр\.|Лит\.|На утрене|На литургии|Свтт\.)/gi)];
   const last=contexts.at(-1)?.[0]||'',context=/утр/i.test(last)?'Утреня':/лит/i.test(last)?'Литургия':/свтт/i.test(last)?'Святителям':'';
   const reference=match[0].trim(),condition=/если|при совершении/i.test(paragraph.slice(0,paragraph.search(pattern)))?'По условию богослужебных указаний':'';
   if(!readings.some(x=>x.reference===reference&&x.context===context&&x.condition===condition))readings.push({kind:gospel?'gospel':'apostle',label:gospel?'Евангелие':'Апостол',reference,context,condition});
  }
 }
 return readings;
}
async function dayReadingsApi(req,env){
 if(req.method!=='GET')return new Response('Method not allowed',{status:405,headers:{Allow:'GET'}});
 const response=await calendarApi(req,env),data=await response.json();if(!response.ok)return json({date:today(),error:'Чтения временно недоступны'},503);
 const readings=extractDayReadings(data.readings);if(!readings.length)return json({date:data.date,error:'Чтения нужно уточнить по источнику'},503);
 return json({date:data.date,readings,readingsUrl:data.readingsUrl});
}
function calendarClient(){
 const box=document.getElementById('day-readings');if(!box)return;
 const status=box.querySelector('.readings-status'),list=box.querySelector('.readings-list');let loaded=false,busy=false,lastAttempt=0;
 async function load(){if(loaded||busy)return;busy=true;lastAttempt=Date.now();status.textContent='Загружаем чтения…';try{
  const response=await fetch('/api/day-readings'),data=await response.json();if(!response.ok||!data.readings?.length)throw new Error();
  if(data.date!==box.dataset.date){status.textContent='Наступил новый день. Обновите расписание, чтобы увидеть его чтения.';return}
  list.replaceChildren();for(const reading of data.readings){const p=document.createElement('p'),label=document.createElement('strong');label.textContent=[reading.context,reading.label].filter(Boolean).join(' · ')+': ';p.append(label,document.createTextNode(reading.reference+(reading.condition?' · '+reading.condition:'')));list.append(p)}
  status.textContent='';status.hidden=true;loaded=true;
 }catch{status.hidden=false;status.textContent='Не удалось загрузить чтения. Откройте тексты по ссылке ниже.'}finally{busy=false}}
 box.addEventListener('toggle',()=>{if(box.open&&!loaded&&Date.now()-lastAttempt>10000)load()});if(box.open)load();
}

function donationUrl(value,kind){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&(kind==='sbp'?['qr.nspk.ru']:['yoomoney.ru','yookassa.ru']).includes(u.hostname)?u.href:''}catch{return ''}}
function donationReady(t){return t.donationConfirmed===true&&!!t.donationRecipient&&/^\d{4}-\d{2}-\d{2}$/.test(t.donationVerifiedAt||'')&&!!(t.donationRequisites||t.donationSbpQr||donationUrl(t.donationSbpUrl,'sbp')||donationUrl(t.donationYooUrl,'yoo'))}
function validateGivingRecord(x){
 if(x.notesNameLimit!==''&&x.notesNameLimit!==undefined&&(!Number.isInteger(Number(x.notesNameLimit))||Number(x.notesNameLimit)<1||Number(x.notesNameLimit)>30))apiError('Лимит имён: целое число от 1 до 30');
 for(const field of ['notesRulesVerifiedAt','donationVerifiedAt'])if(x[field]&&!/^\d{4}-\d{2}-\d{2}$/.test(x[field]))apiError('Укажите дату подтверждения в формате ГГГГ-ММ-ДД');
 if(x.donationConfirmed!==undefined&&typeof x.donationConfirmed!=='boolean')apiError('Подтверждение пожертвований должно быть Да / Нет');
 if(x.donationSbpQr&&!validImage(x.donationSbpQr))apiError('QR СБП должен быть загружен в медиатеку');
 if(x.donationSbpUrl&&!donationUrl(x.donationSbpUrl,'sbp'))apiError('СБП: нужна платёжная https-ссылка qr.nspk.ru');
 if(x.donationYooUrl&&!donationUrl(x.donationYooUrl,'yoo'))apiError('ЮKassa: нужна платёжная https-ссылка yoomoney.ru или yookassa.ru');
 for(const field of ['donationRequisites','notesInstructions'])if(String(x[field]||'').length>5000)apiError('Сократите текст до 5000 символов');
 if(x.donationConfirmed&&!donationReady(x))apiError('Для подключения пожертвований нужны получатель, дата подтверждения и реквизиты, QR или платёжная ссылка');
}
function notesLimit(t){return Number.isInteger(Number(t?.notesNameLimit))&&Number(t.notesNameLimit)>=1&&Number(t.notesNameLimit)<=30?Number(t.notesNameLimit):10}
function notesRules(t){return /^\d{4}-\d{2}-\d{2}$/.test(t?.notesRulesVerifiedAt||'')?String(t.notesInstructions||''):''}
function parseNoteNames(text,limit){const names=String(text).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!names.length)throw new Error('Добавьте хотя бы одно имя.');if(names.length>limit)throw new Error('В одном листе можно указать до '+limit+' имён.');if(names.some(x=>x.length>60||!/^\p{L}[\p{L}\p{M}\s’\x27-]*$/u.test(x)))throw new Error('Укажите только имена: по одному на строке, без цифр и дополнительных сведений.');return names}
function parishGivingLinks(t){return `<div class="document-links parish-giving">${link('/notes?temple='+encodeURIComponent(t.id),'Подготовить записку','btn outline')}${link('/donations?temple='+encodeURIComponent(t.id),'Помочь храму ↗','text-link')}</div>`}
function templeSelect(temples,selected,extras=false){return `<select name="temple" id="giving-temple" required><option value="">Выберите храм</option>${temples.map(t=>`<option value="${esc(t.id)}" ${selected===t.id?'selected':''} ${extras?`data-limit="${notesLimit(t)}" data-rules="${esc(notesRules(t))}"`:''}>${esc(t.name)} · ${esc(t.city)}</option>`).join('')}</select>`}
function notesPage(s,url){const temples=s.churches.filter(visible),selected=temples.some(t=>t.id===url.searchParams.get('temple'))?url.searchParams.get('temple'):'';return head('Записки','Подготовьте записку о здравии или о упокоении для выбранного храма.')+`<div class="wrap detail"><div class="giving-intro"><p>Записку можно составить здесь, распечатать и передать в храм. Онлайн-приём будет доступен после согласования порядка передачи с приходами.</p></div><div class="giving-layout"><div class="giving-panel"><h2>Подготовить записку</h2><form id="note-form" method="post" action="/notes" autocomplete="off"><label for="giving-temple">Храм</label>${templeSelect(temples,selected,true)}<fieldset class="note-types"><legend>Вид поминовения</legend><label><input type="radio" name="kind" value="health" checked> О здравии</label><label><input type="radio" name="kind" value="repose"> О упокоении</label></fieldset><label for="note-names">Имена</label><p id="note-hint" class="small">По одному имени на строке. До ${notesLimit(temples.find(t=>t.id===selected))} имён в одном листе.</p><textarea id="note-names" rows="8" maxlength="1860" aria-describedby="note-hint note-feedback" placeholder="Александра&#10;Марии&#10;Николая" required></textarea><p id="note-count" class="small" aria-live="polite">Имен: 0</p><button id="note-prepare" class="btn" type="submit" disabled>Подготовить записку</button><p id="note-feedback" role="status"></p><noscript><p>Для подготовки и печати записки включите JavaScript или составьте её на бумаге в храме.</p></noscript></form></div><aside class="giving-aside"><h2>Передача в храм</h2><p>Подготовка записки не отправляет её в приход. Передайте распечатанный лист сотруднику выбранного храма; уточните вид и срок поминовения.</p><div id="note-rules" class="notice" hidden></div><p><a id="note-parish" href="${selected?'/temples/'+esc(selected):'/temples'}" class="text-link">Контакты выбранного храма ↗</a></p><h3>Пожертвование храму</h3><p>Поддержать приход можно отдельно. Платёжные способы появятся после подтверждения получателя и реквизитов.</p><a id="note-donate" href="/donations${selected?'?temple='+encodeURIComponent(selected):''}" class="btn outline">Помочь выбранному храму</a><p class="small">Введённые имена остаются на этой странице и не сохраняются на сервере. После закрытия страницы список будет очищен.</p></aside></div><section id="note-result" hidden aria-label="Подготовленная записка"><article id="note-print" class="note-paper"><p class="eyebrow">Записка для передачи в храм</p><h2 id="note-print-title"></h2><p id="note-print-temple"></p><ol id="note-print-names"></ol></article><div class="document-links note-actions"><button id="note-copy" class="btn outline" type="button">Скопировать</button><button id="note-print-button" class="btn" type="button">Распечатать</button></div><p id="note-copy-status" class="small" role="status"></p></section></div>`}
function notesClient(){
 const form=document.getElementById('note-form');if(!form)return;
 const temple=document.getElementById('giving-temple'),names=document.getElementById('note-names'),feedback=document.getElementById('note-feedback'),result=document.getElementById('note-result');let prepared='';
 const parse=PARSE_NOTE_NAMES;
 function option(){return temple.selectedOptions[0]}function limit(){return Number(option().dataset.limit)||10}
 function invalidate(){result.hidden=true;prepared='';document.body.classList.remove('print-note');feedback.textContent=''}
 function update(){invalidate();document.getElementById('note-hint').textContent='По одному имени на строке. До '+limit()+' имён в одном листе.';document.getElementById('note-count').textContent='Имен: '+names.value.split(/\r?\n/).filter(x=>x.trim()).length+' / '+limit();const rules=document.getElementById('note-rules');rules.textContent=option().dataset.rules||'';rules.hidden=!rules.textContent;document.getElementById('note-parish').href=temple.value?'/temples/'+encodeURIComponent(temple.value):'/temples';document.getElementById('note-donate').href='/donations'+(temple.value?'?temple='+encodeURIComponent(temple.value):'')}
 document.getElementById('note-prepare').disabled=false;temple.addEventListener('change',update);names.addEventListener('input',update);form.querySelectorAll('[name=kind]').forEach(x=>x.addEventListener('change',invalidate));update();
 form.addEventListener('submit',ev=>{ev.preventDefault();invalidate();if(!temple.value){feedback.textContent='Выберите храм.';temple.focus();return}try{const list=parse(names.value,limit()),title=form.elements.kind.value==='repose'?'О упокоении':'О здравии';document.getElementById('note-print-title').textContent=title;document.getElementById('note-print-temple').textContent=option().textContent;const ol=document.getElementById('note-print-names');ol.replaceChildren();for(const name of list){const li=document.createElement('li');li.textContent=name;ol.append(li)}prepared=title+'\n'+option().textContent+'\n\n'+list.join('\n');result.hidden=false;document.getElementById('note-copy-status').textContent='';feedback.textContent='Записка подготовлена. Распечатайте или скопируйте её и передайте в храм.';document.body.classList.add('print-note');result.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){feedback.textContent=error.message;names.focus()}});
 document.getElementById('note-copy').onclick=async()=>{try{await navigator.clipboard.writeText(prepared);document.getElementById('note-copy-status').textContent='Скопировано.'}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(document.getElementById('note-print'));selection.removeAllRanges();selection.addRange(range);document.getElementById('note-copy-status').textContent='Текст выделен. Скопируйте его вручную.'}};
 document.getElementById('note-print-button').onclick=()=>window.print();
}
function donationCard(t){const ready=donationReady(t);return `<article class="giving-panel"><p class="eyebrow">${esc(t.city)}</p><h2>${esc(t.name)}</h2>${ready?`<p class="small">Получатель</p><p class="donation-recipient"><strong>${esc(t.donationRecipient)}</strong></p>${t.donationPurpose?'<p>'+esc(t.donationPurpose)+'</p>':''}<div class="donation-methods">${t.donationSbpQr&&validImage(t.donationSbpQr)?`<figure class="donation-qr"><img src="${esc(t.donationSbpQr)}" alt="QR СБП для пожертвования: ${esc(t.donationRecipient)}" width="240" height="240"><figcaption>СБП · проверьте получателя в приложении банка</figcaption></figure>`:''}<div class="document-links">${donationUrl(t.donationSbpUrl,'sbp')?`<a class="btn" href="${esc(donationUrl(t.donationSbpUrl,'sbp'))}" target="_blank" rel="noopener noreferrer">Пожертвовать через СБП ↗</a>`:''}${donationUrl(t.donationYooUrl,'yoo')?`<a class="btn outline" href="${esc(donationUrl(t.donationYooUrl,'yoo'))}" target="_blank" rel="noopener noreferrer">Оплата через ЮKassa ↗</a>`:''}</div></div>${t.donationRequisites?`<h3>Банковские реквизиты</h3><pre class="bank-details">${esc(t.donationRequisites)}</pre><button type="button" class="chip copy-requisites">Скопировать реквизиты</button><p class="small copy-status" role="status"></p>`:''}<p class="small">Реквизиты подтверждены ${esc(dateLabel(t.donationVerifiedAt))}. Сумму пожертвования выбираете вы.</p>`:`<p>Онлайн-пожертвования для этого храма ещё не подключены. Реквизиты и QR СБП появятся после подтверждения приходом.</p><p>О способах помочь храму можно узнать у сотрудников прихода.</p>`}<div class="document-links">${phoneButtons(t)}${link('/temples/'+t.id,'Страница и контакты храма ↗','text-link')}</div></article>`}
function donationsPage(s,url){const temples=s.churches.filter(visible),selected=temples.find(t=>t.id===url.searchParams.get('temple'));return head('Пожертвования','Поддержите приход: забота о храме, богослужебной и приходской жизни.')+`<div class="wrap detail"><div class="giving-intro"><p>Выберите храм, которому хотите помочь. Для каждого прихода публикуются его собственные подтверждённые реквизиты и способы пожертвования.</p></div><form class="filters" action="/donations" method="get"><label for="giving-temple">Храм${templeSelect(temples,selected?.id||'')}</label><button class="btn" type="submit">Показать способы</button></form>${selected?donationCard(selected):`<div class="notice"><div><h2>Кому вы хотите помочь?</h2><p>Выберите приход в списке выше. Если онлайн-оплата пока не подключена, здесь будут доступны контакты храма.</p></div></div>${temples.filter(donationReady).map(donationCard).join('')}`}<p class="small" style="margin:28px 0 50px">Пожертвование добровольно. Подготовить записку для передачи в храм можно в ${link('/notes'+(selected?'?temple='+encodeURIComponent(selected.id):''),'разделе «Записки»','text-link')}.</p></div>`}
function donationsClient(){document.querySelectorAll('.copy-requisites').forEach(button=>{button.onclick=async()=>{const card=button.closest('article'),status=card.querySelector('.copy-status');try{await navigator.clipboard.writeText(card.querySelector('.bank-details').textContent);status.textContent='Реквизиты скопированы.'}catch{status.textContent='Выделите реквизиты и скопируйте их вручную.'}}})}
