const CATHEDRAL_ID='temple-1';
function calendarTextTone(text){if(/богородиц|икон[аы].*божией матери/i.test(text))return 'mary';return calendarFeastLevel(text)?'lord':'daily'}
const scheduleTones=new Set(['lord','mary','saint','doxology','daily']);
function shiftDay(date,days){return new Date(Date.parse(date+'T12:00:00Z')+days*86400000).toISOString().slice(0,10)}
function dayOfWeek(date){return new Date(date+'T12:00:00Z').getUTCDay()}
function weekdayLabel(date){return new Intl.DateTimeFormat('ru-RU',{weekday:'long',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))}
function isEveningOffice(x){return x.liturgicalDate?x.liturgicalDate!==x.date:/вечер|всенощ|полиеле/i.test(x.title)&&x.time>='12:00'}
function liturgicalDate(x){return x.liturgicalDate||shiftDay(x.date,isEveningOffice(x)?1:0)}
function dayMemory(state,date){const rows=state.services.filter(x=>x.templeId===CATHEDRAL_ID&&x.date===date&&visible(x));const row=rows.find(x=>x.dayMemory);return row?{title:row.dayMemory,tone:row.dayTone||'daily'}:CATHEDRAL_DAYS[date]||{title:'Память дня — '+dateLabel(date),tone:'daily',unknown:true}}
function memoryForService(x,state){const date=liturgicalDate(x),memory=dayMemory(state,date);const title=x.commemoration||memory.title;let tone=x.commemorationTone||memory.tone;const level=calendarFeastLevel(title);if(!x.commemorationTone){if(calendarTextTone(title)!=='daily')tone=calendarTextTone(title);else if(/полиеле/i.test(x.title)&&tone==='daily')tone='saint';else if(x.serviceRank==='doxology')tone='doxology'}return {date,title,tone:scheduleTones.has(tone)?tone:'daily',level,unknown:memory.unknown&&!x.commemoration}}
function clergyLink(id,state,fallback){const c=state.clergy.find(c=>c.id===id&&visible(c));return c?link('/clergy/'+id,esc(fallback),'celebrant-link'):esc(fallback)}
function serviceCelebrant(x,state){
 const override=(x.celebrant||x.note?.match(/(?:Совершает|Возглавляет|Служит)\s+([^\n]+?)(?:\.\s|\.$|$)/i)?.[1]||'').replace(/^(?:Совершает|Возглавляет|Служит)\s+/i,'');
 if(override){const bishop=/епископ|архиепископ|митрополит|патриарх/i.test(override),id=x.celebrantId||state.clergy.find(c=>visible(c)&&c.name.split(',')[0].split(/\s+/).every(part=>override.toLowerCase().includes(part.toLowerCase())))?.id||'';return {html:(bishop||scheduleKindMatches('baptism',x,'service')?'Совершает ':'Служит ')+(id?clergyLink(id,state,override):esc(override)),id,key:id||'named:'+override,bishop,collective:false,label:override}}
 const memory=memoryForService(x,state),civilWeekday=dayOfWeek(x.date),day=dayOfWeek(memory.date);
 const principalOffice=/литурги|вечер|всенощ|полиеле|утрен/i.test(x.title);
 const collective=(civilWeekday===6&&isEveningOffice(x)&&/всенощ/i.test(x.title))||(civilWeekday===0&&x.time<'12:00'&&/литурги/i.test(x.title))||(!!memory.level&&principalOffice);
 if(collective)return {html:'Соборно · предстоятель '+clergyLink('clergy-20',state,'протоиерей Павел Плотников'),id:'clergy-20',key:'clergy-20',collective:true,bishop:false};
 // A Sunday afternoon moleben belongs to the Sunday memory, but the duty priest is already Medvedev.
 if(day===0&&!isEveningOffice(x)&&x.time<'12:00')return {html:'Духовенство собора',id:'',key:'clergy',label:'Духовенство собора',collective:false,bishop:false};
 const [id,name]=[0,1,2].includes(day)?['clergy-13','иерей Филипп Медведев']:[3,4].includes(day)?['clergy-10','иерей Евгений Ильин']:['clergy-14','иерей Даниил Морозов'];
 return {html:'Служит '+clergyLink(id,state,name),id,key:id,label:name,collective:false,bishop:false};
}
function eveningServiceTitle(x,state){
 if(!isEveningOffice(x))return x.title;
 const memory=memoryForService(x,state),known=CATHEDRAL_DAYS[memory.date];
 const dedication=x.serviceDedication||(!x.commemoration&&known?.title===memory.title?known.dedication:'');
 const name=/всенощ/i.test(x.title)?'Всенощное бдение':/полиеле/i.test(x.title)?'Полиелейное богослужение':'Вечернее богослужение';
 let extra='';if(/акафист/i.test(x.title))extra=/(?:Амвроси|Амвросию)/i.test(dedication)?'. Акафист':'. '+x.title.slice(x.title.search(/акафист/i));
 if(/исповед/i.test(x.title))extra+='. Исповедь';
 return name+(dedication?' '+dedication:memory.unknown?'':' — '+memory.title.replace(/\s*День постный\.?/i,'').replace(/\.$/,''))+extra;
}
function eventCelebrant(x,state){if(!x.celebrant&&!x.celebrantId)return null;const c=state.clergy.find(c=>c.id===x.celebrantId&&visible(c));let name=x.celebrant;if(!name&&c){const parts=c.name.split(',')[0].split(/\s+/);name=c.rank+' '+parts.slice(1).join(' ')+' '+parts[0]}if(!name)return null;const leader=serviceCelebrant({...x,celebrant:name},state),verb=x.scheduleType==='service'?'Совершает ':/бесед.*крещ|крещ.*бесед/i.test(x.title)?'Проводит ':'Ведёт ';return {...leader,html:leader.html.replace(/^(?:Служит|Совершает)\s+/,verb)}}
function priestMatches(x,state,priest=''){if(!priest)return true;const c=x.templeId?serviceCelebrant(x,state):eventCelebrant(x,state);if(!c)return false;return priest==='collective'?c.collective:priest===c.key||priest===c.id}
function priestChoices(){return [['','Все священнослужители'],['collective','Соборно'],['clergy-20','Протоиерей Павел Плотников'],['clergy-13','Иерей Филипп Медведев'],['clergy-10','Иерей Евгений Ильин'],['clergy-14','Иерей Даниил Морозов'],['clergy-19','Диакон Димитрий Плотников']]}

function cathedralServiceRow(x,state){const memory=memoryForService(x,state),celebrant=serviceCelebrant(x,state);let note=x.note||'';const civilMemory=dayMemory(state,x.date).title;if(civilMemory)note=note.replace(civilMemory,'').trim();note=note.replace(/(?:Совершает|Возглавляет|Служит)\s+[^\n]+?(?:\.\s|\.$|$)/i,'').trim();const specialTime=dayOfWeek(x.date)===0&&x.time<'12:00'&&/исповед|часы|литурги/i.test(x.title);return `<article class="cathedral-service ${memory.tone==='daily'?'daily-service':''} ${celebrant.bishop?'hierarch-service':''}" data-service-date="${esc(x.date)}" data-liturgical-date="${esc(memory.date)}"><time class="${specialTime?'sunday-special-time':''}" datetime="${esc(x.date+'T'+x.time+':00+07:00')}">${esc(x.time)}</time><div class="service-content"><h4>${esc(eveningServiceTitle(x,state))}</h4><p class="service-celebrant ${celebrant.bishop?'hierarch':''}">${celebrant.html}</p>${note?'<p class="service-annotation">'+esc(note)+'</p>':''}</div></article>`}
function cathedralRecords(state,{from,until,kind='',priest=''}={}){return state.services.filter(x=>x.templeId===CATHEDRAL_ID&&visible(x)&&x.confirmedUntil>=x.date&&(!from||x.date>=from)&&(!until||x.date<=until)&&scheduleKindMatches(kind,x,'service')&&priestMatches(x,state,priest)).map(x=>({kind:'service',record:x,date:x.date,time:x.time})).concat(state.events.filter(x=>x.org===CATHEDRAL_ID&&(visible(x)||x.status==='cancelled')&&(!from||x.date.slice(0,10)>=from)&&(!until||x.date.slice(0,10)<=until)&&scheduleKindMatches(kind,x,x.scheduleType==='service'?'service':'event')&&priestMatches(x,state,priest)).map(x=>({kind:'event',record:x,date:x.date.slice(0,10),time:x.timeUnknown||x.date.length===10?'99:99':x.date.slice(11,16)}))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function dayReadingsWidget(date){return `<details class="day-readings" id="day-readings" data-date="${esc(date)}"><summary>Чтения дня</summary><div class="day-readings-content"><p class="readings-status" role="status">Евангелие и Апостол</p><div class="readings-list"></div><a class="text-link" href="https://azbyka.ru/biblia/days/${esc(date)}" target="_blank" rel="noopener noreferrer">Читать тексты чтений ↗</a></div></details>`}
function cathedralTimeline(state,options={}){
 const currentDay=options.currentDay||today(),records=cathedralRecords(state,options),days=[...new Set(records.map(x=>x.date))];
 const includeReadings=options.includeReadings&&(!options.from||currentDay>=options.from)&&(!options.until||currentDay<=options.until);
 if(includeReadings&&!days.includes(currentDay))days.push(currentDay);days.sort();
 if(!days.length)return '<div class="empty"><h3>Подходящих записей нет</h3><p>Измените фильтры или откройте прошлые службы.</p></div>';
 return '<div class="cathedral-timeline">'+days.map(date=>{const rows=records.filter(x=>x.date===date),memory=dayMemory(state,date),tone=dayOfWeek(date)===0?'lord':calendarTextTone(memory.title)==='daily'?memory.tone:calendarTextTone(memory.title);return `<section class="schedule-day ${dayOfWeek(date)===0?'is-sunday':''}" data-date="${date}"><div class="schedule-day-heading tone-${scheduleTones.has(tone)?tone:'daily'}"><div class="schedule-day-date"><h2>${esc(weekdayLabel(date))}</h2><time datetime="${date}">${esc(dateLabel(date))}</time></div><div class="day-memory" data-memory-date="${esc(date)}"><h3>${memory.unknown?'':esc(memory.title)}</h3></div>${date===currentDay?'<span class="today-label">Сегодня</span>':''}${includeReadings&&date===currentDay?dayReadingsWidget(date):''}</div><div class="schedule-day-body">${rows.map(row=>{
 if(row.kind==='event'){const x=row.record,leader=eventCelebrant(x,state),program=eventProgram(x,state),unknown=x.timeUnknown||x.date.length===10;return `<article class="cathedral-service ${x.scheduleType==='service'?'sacrament-row':'meeting-row'}" data-event-id="${esc(x.id)}"><time>${unknown?'—':esc(eventTimeLabel(x))}</time><div class="service-content"><h4>${esc(x.title)}${x.status==='cancelled'?' · отменено':''}</h4>${leader?'<p class="service-celebrant">'+leader.html+'</p>':''}${unknown?'<p class="service-annotation">Время начала уточняется в храме.</p>':''}${x.note?'<p class="service-annotation">'+esc(x.note)+'</p>':''}${program?'<p class="service-annotation">'+link('/events/'+program.id,'Об участии','text-link')+'</p>':''}</div></article>`}

 return cathedralServiceRow(row.record,state);
 }).join('')||'<p class="schedule-no-matches">На сегодня записей по выбранным фильтрам нет.</p>'}</div></section>`}).join('')+'</div>';
}

function cathedralWeek(state,url,at=today()){const dates=state.services.filter(x=>x.templeId===CATHEDRAL_ID&&visible(x)&&x.confirmedUntil>=x.date).map(x=>x.date).concat(state.events.filter(x=>x.org===CATHEDRAL_ID&&(visible(x)||x.status==='cancelled')).map(x=>x.date.slice(0,10))).sort(),last=dates.at(-1)||at,first=dates[0]||at,archive=url.searchParams.get('archive')==='1';let from=url.searchParams.get('from');if(!/^\d{4}-\d{2}-\d{2}$/.test(from||'')||!Number.isFinite(Date.parse(from))||new Date(from+'T12:00:00Z').toISOString().slice(0,10)!==from)from=archive?shiftDay(at,-7):at;if(archive&&from>=at)from=shiftDay(at,-7);if(!archive&&from<at)from=at;const until=archive?[shiftDay(from,6),shiftDay(at,-1)].sort()[0]:[from,last].sort().at(-1);return {from,until,last,first,archive,currentDay:at}}
function scheduleLegend(){return `<details class="schedule-legend"><summary>Цвета заголовков</summary><ul><li class="tone-lord">Воскресенья и Господские праздники</li><li class="tone-mary">Богородичные праздники и почитаемые иконы</li><li class="tone-saint">Память почитаемых святых</li><li class="tone-doxology">Славословные службы</li><li class="tone-daily">Вседневные дни</li></ul></details>`}
function cathedralSchedulePage(state,url,at=today()){const period=cathedralWeek(state,url,at),kind=scheduleKinds.some(([key])=>key===url.searchParams.get('kind'))?url.searchParams.get('kind'):'',choices=priestChoices(state),priest=choices.some(([key])=>key===url.searchParams.get('priest'))?url.searchParams.get('priest'):'';const temple=state.churches.find(t=>t.id===CATHEDRAL_ID);const navUrl=(from,archive=period.archive,filtered=true)=>'/schedule?'+new URLSearchParams({...(from?{from}:{}),...(archive?{archive:'1'}:{}),...(filtered&&kind?{kind}:{}),...(filtered&&priest?{priest}:{})}).toString();return head('Расписание Преображенского собора','Преображенский кафедральный собор · Бердск, ул. Горького, 44. Время Новосибирска (UTC+7).').replace('wrap page-head','wrap page-head schedule-page-head')+`<div class="wrap cathedral-schedule"><p class="schedule-intro">${link('/temples','Расписание богослужений и работа других храмов благочиния','text-link')}</p><div class="schedule-week-nav"><div>${period.archive?(period.from>period.first?link(navUrl(shiftDay(period.from,-7)),'← Ранее','chip'):''):link(navUrl(shiftDay(at,-7),true),'Прошлые службы','text-link')}</div><h2>${period.archive?'Прошлые службы · ':''}${esc(dateLabel(period.from).replace(/ \d{4} г\./,''))}${period.until!==period.from?' — '+esc(dateLabel(period.until)):''}</h2><div>${period.archive?link(navUrl('',false),'Сегодня и ближайшие службы','text-link'):''}</div></div>${period.archive&&period.until<shiftDay(at,-1)?'<p class="small">'+link(navUrl(shiftDay(period.from,7)),'Позднее →','text-link')+'</p>':''}<form class="filters cathedral-filters" action="/schedule"><input type="hidden" name="from" value="${esc(period.from)}">${period.archive?'<input type="hidden" name="archive" value="1">':''}<label>Вид службы или встречи<select name="kind">${scheduleKinds.map(([key,label])=>`<option value="${key}" ${kind===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Кто служит<select name="priest">${choices.map(([key,label])=>`<option value="${esc(key)}" ${priest===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label><button class="btn">Показать</button>${kind||priest?link(navUrl(period.from,period.archive,false),'Сбросить фильтры','text-link'):''}</form>${scheduleLegend()}${!period.archive&&period.last<at?'<p class="small">Новое расписание ещё не опубликовано. Предыдущие записи доступны по ссылке «Прошлые службы».</p>':''}${cathedralTimeline(state,{...period,kind,priest,includeReadings:!period.archive})}${temple?.scheduleImage?'<details class="schedule-original"><summary>Оригинал расписания собора</summary>'+scheduleOriginal(temple)+'</details>':''}<p class="small schedule-footnote">День и время слева — дата посещения храма. Посвящение вечерней службы относится к следующему дню. Состав духовенства указан по обычному графику с учётом опубликованных исключений.</p><div class="document-links" style="margin:18px 0 30px"><button class="btn outline" onclick="window.print()">Распечатать</button>${link('/calendar.ics?'+new URLSearchParams({temple:CATHEDRAL_ID,from:period.from,until:period.until,kind:kind||'',priest:priest||''}).toString(),'Скачать календарь ICS','btn outline')}${link('/events?temple=temple-1','Приходская жизнь собора','text-link')}</div></div>`}

function parishServiceInfo(t,state){if(t.id===CATHEDRAL_ID)return `<h2>Расписание собора</h2><p>Богослужения и встречи на неделю, память дня и духовенство.</p>${link('/schedule','Открыть расписание Преображенского собора','btn')}`;return `<h2>Богослужения и часы открытия</h2><div class="parish-routine"><div><h3>Богослужения</h3>${paragraphs(t.regularServices||'Богослужения совершаются по приходскому расписанию. Дни и время уточняйте в храме.')}</div><div><h3>Храм открыт</h3>${paragraphs(t.openingHours||'Дни и часы открытия уточняйте у сотрудников прихода.')}</div></div><p class="small">В праздничные дни порядок богослужений может меняться. Перед поездкой уточните время в приходе.</p><div class="document-links">${phoneButtons(t)}${link('/contacts','Контакты приходов','text-link')}</div>`}
function applyCathedralPresentation(state){const marker='cathedral-presentation-20261018';if(state.contentMigrations.includes(marker))return false;for(const x of state.services.filter(x=>x.templeId===CATHEDRAL_ID)){const memory=CATHEDRAL_DAYS[x.date];if(memory){x.dayMemory??=memory.title;x.dayTone??=memory.tone;x.note=(x.note||'').replace(memory.title,'').trim()}}
 const t=state.churches.find(t=>t.id===CATHEDRAL_ID);if(t)t.schedulePeriodStart='2026-10-18';for(const a of state.announcements||[])if(a.id==='schedule-october2026')a.text=(a.text||'').replace('в общее расписание','в расписание Преображенского собора');
 // Preserve old dated schedules as editorial history, never convert them to recurring rules.
 state.contentMigrations.push(marker);state.audit??=[];state.audit.push({date:now(),action:marker,actor:'По поручению иерея Евгения'});return true}
// Maintain confirmed weekly parish activities alongside each published Sunday.
// Existing records (including cancelled or edited ones) are reused; no unbounded recurrence is generated.
function applyCathedralActivities(state){
 let changed=false;const marker='cathedral-activities-20261018';state.contentMigrations??=[];
 const child=state.programs.find(x=>x.id==='sunday-school'&&x.org===CATHEDRAL_ID),talks=state.programs.find(x=>x.id==='baptism-talks'&&x.org===CATHEDRAL_ID);
 if(!state.contentMigrations.includes(marker)){
  if(child){child.title='Детская воскресная школа';changed=true}
  if(talks){talks.leaders='Беседу перед Крещением проводит диакон Димитрий Плотников.';changed=true}
  if(!state.programs.some(x=>x.id==='sunday-school-adults'))state.programs.push({id:'sunday-school-adults',org:CATHEDRAL_ID,status:'published',title:'Воскресная школа для взрослых',category:'Взрослые и образование',summary:'Воскресные занятия для взрослых с иереем Евгением Ильиным.',schedule:'По воскресеньям, 12:10',audience:'Взрослые',leaders:'Иерей Евгений Ильин',description:'Занятия воскресной школы для взрослых в Преображенском кафедральном соборе.',purpose:'Изучение православной веры и обсуждение вопросов церковной жизни.',participation:'О занятиях можно узнать в Преображенском соборе.',confirmedBy:'Иерей Евгений Ильин, сообщение 18 октября 2026 года',verifiedAt:'2026-10-18'});
  state.contentMigrations.push(marker);changed=true;
 }
 for(const x of state.events.filter(x=>x.org===CATHEDRAL_ID)){
  if(x.programId==='sunday-school'||x.title==='Воскресная школа'){if(x.title==='Воскресная школа'){x.title='Детская воскресная школа';changed=true}if(!x.programId){x.programId='sunday-school';changed=true}}
  if((x.programId==='baptism-talks'||/бесед.*крещ|крещ.*бесед/i.test(x.title))&&!x.celebrant&&!x.celebrantId){Object.assign(x,{celebrant:'диакон Димитрий Плотников',celebrantId:'clergy-19'});changed=true}
 }
 const sundays=[...new Set(state.services.filter(x=>x.templeId===CATHEDRAL_ID&&visible(x)&&x.date>='2026-10-18'&&x.confirmedUntil>=x.date&&dayOfWeek(x.date)===0).map(x=>x.date))];
 for(const date of sundays){
  const base={org:CATHEDRAL_ID,status:'published',location:'Преображенский кафедральный собор, Бердск, ул. Горького, 44',sourceLabel:'Уточнение иерея Евгения Ильина от 18 октября 2026 года'};
  const childExists=state.events.some(x=>x.org===CATHEDRAL_ID&&x.date.slice(0,10)===date&&(x.programId==='sunday-school'||/детская воскресная школа/i.test(x.title)));
  if(!childExists){state.events.push({...base,id:'cathedral-school-children-'+date,programId:'sunday-school',title:'Детская воскресная школа',date:date+'T11:30:00+07:00',timeUnknown:false});changed=true}
  if(!state.events.some(x=>x.org===CATHEDRAL_ID&&x.date.slice(0,10)===date&&(x.programId==='sunday-school-adults'||/воскресная школа для взрослых/i.test(x.title)))){state.events.push({...base,id:'cathedral-school-adults-'+date,programId:'sunday-school-adults',title:'Воскресная школа для взрослых',date:date+'T12:10:00+07:00',timeUnknown:false,celebrant:'иерей Евгений Ильин',celebrantId:'clergy-10'});changed=true}
  const baptism=state.events.find(x=>x.org===CATHEDRAL_ID&&x.date.slice(0,10)===date&&scheduleKindMatches('baptism',x,'event'))||state.services.find(x=>x.templeId===CATHEDRAL_ID&&x.date===date&&scheduleKindMatches('baptism',x,'service'));
  if(!baptism){state.events.push({...base,id:'cathedral-baptism-'+date,title:'Таинство Крещения',date:date+'T11:00:00+07:00',timeUnknown:false,location:'Преображенский кафедральный собор, нижний храм, Бердск, ул. Горького, 44',note:'Нижний храм.',scheduleType:'service',celebrant:'иерей Филипп Медведев',celebrantId:'clergy-13'});changed=true}
  else if(!baptism.celebrant&&!baptism.celebrantId){Object.assign(baptism,{celebrant:'иерей Филипп Медведев',celebrantId:'clergy-13'});changed=true}
 }
 if(changed){state.audit??=[];state.audit.push({date:now(),action:marker,actor:'По поручению иерея Евгения'});state.audit=state.audit.slice(-300)}return changed;
}
function applyCathedralBaptismTime(state){
 const marker='cathedral-baptism-time-20261018';if(state.contentMigrations.includes(marker))return false;
 for(const x of state.events.filter(x=>x.org===CATHEDRAL_ID&&x.date.slice(0,10)>='2026-10-18'&&dayOfWeek(x.date.slice(0,10))===0&&scheduleKindMatches('baptism',x,'event'))){x.date=x.date.slice(0,10)+'T11:00:00+07:00';x.timeUnknown=false;x.scheduleType='service';x.location='Преображенский кафедральный собор, нижний храм, Бердск, ул. Горького, 44';if(!/нижн(?:ий|ем|его) храм/i.test(x.note||''))x.note=[x.note,'Нижний храм.'].filter(Boolean).join(' ')}
 for(const x of state.services.filter(x=>x.templeId===CATHEDRAL_ID&&x.date>='2026-10-18'&&dayOfWeek(x.date)===0&&scheduleKindMatches('baptism',x,'service'))){x.time='11:00';if(!/нижн(?:ий|ем|его) храм/i.test(x.note||''))x.note=[x.note,'Нижний храм.'].filter(Boolean).join(' ')}
 const talks=state.programs.find(x=>x.id==='baptism-talks'&&x.org===CATHEDRAL_ID);if(talks&&!/Воскресное Крещение/.test(talks.participation||''))talks.participation=(talks.participation||'')+'\n\nВоскресное Крещение совершается в 11:00 в нижнем храме Преображенского собора. Совершает иерей Филипп Медведев.';
 const memorial=state.services.find(x=>x.id==='cathedral-20261020-1200'&&x.templeId===CATHEDRAL_ID);if(memorial&&!/за алтар[её]м/i.test(memorial.note||''))memorial.note=[memorial.note,'В день тезоименитства епископа Сергия (Соколова), на его могиле за алтарём Преображенского собора.'].filter(Boolean).join(' ');
 state.contentMigrations.push(marker);state.audit??=[];state.audit.push({date:now(),action:marker,actor:'По поручению иерея Евгения'});return true;
}
function homeWorshipRecords(state,at=new Date()){
 const services=state.services.filter(x=>x.templeId===CATHEDRAL_ID).concat(state.events.filter(x=>x.org===CATHEDRAL_ID&&x.scheduleType==='service'&&!x.timeUnknown&&x.date.length>10).map(x=>{const date=x.date.slice(0,10),memory=dayMemory(state,date);return {...x,templeId:CATHEDRAL_ID,date,time:x.date.slice(11,16),confirmedUntil:date,dayMemory:memory.title,dayTone:memory.tone}}));return homeServiceRecords({...state,services},at);
}
function homeWeekHighlight(state,at=new Date()){
 const x=state.services.find(x=>x.id==='cathedral-20261020-1200'&&x.templeId===CATHEDRAL_ID&&visible(x)&&x.confirmedUntil>=x.date);if(!x||new Date(x.date+'T'+x.time+':00+07:00')<=at)return '';
 const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(at),day=['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-'),weekEnd=shiftDay(day,(7-dayOfWeek(day))%7);
 return `<aside class="home-week-highlight" aria-label="Особое богослужение недели"><p class="eyebrow">${x.date<=weekEnd?'На этой неделе':'На предстоящей неделе'}</p><h3>${esc(weekdayLabel(x.date).replace(/^./,c=>c.toLocaleUpperCase('ru-RU')))}, ${esc(dateLabel(x.date))} · ${esc(x.time)}</h3><p>В день тезоименитства епископа Сергия (Соколова) на его могиле за алтарём Преображенского собора <strong>панихиду совершит епископ Каинский и Барабинский Владимир</strong>.</p></aside>`;
}
