const ORIGIN='https://preobrazhenskoe-berdsk.i-prist.chatgpt.site';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const now=()=>new Date().toISOString();
const today=()=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')};
const dateLabel=d=>d?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Novosibirsk'}).format(new Date(d.length===10?d+'T12:00:00+07:00':d)):'';
const visible=(x)=>x.status==='published'&&(!x.publishAt||new Date(x.publishAt)<=new Date());
const nav=[['/temples','Храмы'],['/schedule','Расписание'],['/news','Новости'],['/clergy','Духовенство'],['/events','События и жизнь прихода'],['/contacts','Контакты']];
const arrow='<span aria-hidden="true">→</span>';
function link(url,label,cls=''){let internal=false;try{internal=new URL(url,ORIGIN).origin===ORIGIN}catch{}if(internal)label=String(label).replace(/\s*↗/g,'');return `<a class="${cls}" href="${esc(url)}">${label}</a>`}
function sourceTag(){return ''}
// Public fields are editorial content. Administrative notes are separate fields
// omitted by the public templates, never inferred from words in a sentence.
function publicText(text){return String(text||'').replace(/\r\n?/g,'\n').trim()}
function paragraphs(text){return publicText(text).split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}
function references(){return ''}
function hasMap(t){return /^\d{1,20}$/.test(t.mapOid||'')&&t.latitude!==undefined&&t.longitude!==undefined&&Number.isFinite(Number(t.latitude))&&Number.isFinite(Number(t.longitude))&&Math.abs(Number(t.latitude))<=90&&Math.abs(Number(t.longitude))<=180}
function mapUrl(t){return hasMap(t)?'https://yandex.ru/map-widget/v1/?ol=biz&oid='+t.mapOid+'&lang=ru_RU':''}
function routeUrl(t){return hasMap(t)?'https://yandex.ru/maps/?rtext=~'+encodeURIComponent(t.latitude+','+t.longitude)+'&rtt=auto':'https://yandex.ru/maps/?text='+encodeURIComponent(t.name+' '+t.address)}
const parishVkUrls=Object.freeze({
 'temple-1':'https://vk.ru/berdsk_sobor',
 'temple-2':'https://vk.ru/sretensky_hram_berdsk',
 'temple-3':'https://vk.ru/hram_bogoyavleniya_berdsk',
 'temple-5':'https://vk.ru/hram_kladb_berdsk',
 'temple-8':'https://vk.ru/public218649816',
 'temple-9':'https://vk.ru/prihod_novolugovoe'
});
function parishVkButton(t){return parishVkUrls[t.id]?link(parishVkUrls[t.id],'Приход во ВКонтакте ↗','btn outline'):''}
function phoneButtons(t){return (t.phoneNumbers||'').split('\n').filter(Boolean).map(row=>{const [label,p]=row.split(' | ');return /^\+7\d{10}$/.test(p?.trim())?link('tel:'+p.trim(),esc(label)+' · '+esc(p.trim()),'btn outline'):''}).join('')+parishVkButton(t)}
function templeMap(t){return hasMap(t)?`<section id="map" style="padding:20px 0"><details class="map-reveal"><summary class="btn outline">НАЙТИ НА КАРТЕ</summary><iframe data-map-src="${esc(mapUrl(t))}" title="Яндекс Карты: ${esc(t.name)}" loading="lazy" style="width:100%;height:420px;border:1px solid var(--line);margin-top:16px" allowfullscreen></iframe><p>${link(routeUrl(t),'Построить маршрут ↗','text-link')}</p></details></section>`:`<section id="map" style="padding:20px 0">${link(routeUrl(t),'НАЙТИ НА КАРТЕ ↗','btn outline')}</section>`}
function overviewUrl(list){const ts=list.filter(hasMap).sort((a,b)=>(a.id==='temple-1'?-1:b.id==='temple-1'?1:0));const pt=ts.map((t,i)=>t.longitude+','+t.latitude+','+(t.id==='temple-1'?'pm2ywl':'pm2blm')+(i+1)).join('~');const xs=ts.map(t=>Number(t.longitude)),ys=ts.map(t=>Number(t.latitude));return 'https://yandex.ru/map-widget/v1/?lang=ru_RU&ll='+encodeURIComponent(((Math.min(...xs)+Math.max(...xs))/2)+','+((Math.min(...ys)+Math.max(...ys))/2))+'&z=9&pt='+encodeURIComponent(pt)}
function mapCatalog(list){const ts=list.filter(hasMap).sort((a,b)=>(a.id==='temple-1'?-1:b.id==='temple-1'?1:0));return ts.length?`<section id="temples-map" style="padding:35px 0"><div class="section-head"><div><p class="eyebrow">Бердск и Новосибирский район</p><h2>Наши храмы на карте</h2></div>${link('/temples','Все храмы ↗','text-link')}</div><p class="small">В каталоге ${list.length} приходов; на карте отмечены ${ts.length} с подтверждённым местоположением.</p>${list.some(t=>!hasMap(t))?'<p class="small">Пока без отметки на карте: '+list.filter(t=>!hasMap(t)).map(t=>link('/temples/'+t.id,esc(t.name),'text-link')).join('; ')+'.</p>':''}<iframe id="catalog-map" src="${esc(overviewUrl(ts))}" title="Карта храмов Преображенского благочиния" loading="lazy" style="width:100%;height:600px;border:1px solid var(--line)" allowfullscreen></iframe><div class="document-links" style="margin-top:20px">${ts.map((t,i)=>`<a class="chip ${i===0?'active':''}" href="/temples/${esc(t.id)}">${i+1}. ${esc(t.name)}</a>`).join('')}</div><p>${link('/temples/'+ts[0].id,esc(ts[0].name)+' ↗','text-link')} · ${link(routeUrl(ts[0]),'Маршрут к собору ↗','text-link')}</p></section>`:''}
const mapsScript=`document.querySelectorAll('.map-reveal').forEach(d=>d.addEventListener('toggle',()=>{const f=d.querySelector('iframe');if(d.open&&!f.hasAttribute('src'))f.src=f.dataset.mapSrc;}));document.querySelectorAll('[data-map-choice]').forEach(b=>b.addEventListener('click',()=>{const f=document.querySelector('#catalog-map');f.src=b.dataset.mapChoice;f.title='Яндекс Карты: '+b.dataset.mapLabel;f.hidden=false;document.querySelector('#catalog-map-status').textContent=b.dataset.mapLabel;const a=document.querySelector('#catalog-map-page').previousElementSibling;a.href=b.dataset.mapPage;document.querySelectorAll('[data-map-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));`;
