function localHref(href,route='/'){
 if(!href||href.startsWith('#')||/^(?:tel:|mailto:|data:|blob:|javascript:)/i.test(href))return href;
 const u=new URL(href.replaceAll('&amp;','&'),new URL(route,'https://preobrazhenskoe-berdsk.i-prist.chatgpt.site'));
 if(u.origin!=='https://preobrazhenskoe-berdsk.i-prist.chatgpt.site')return href;
 if(u.pathname.startsWith('/assets/'))return ASSET_FILES[u.pathname.split('/').at(-1)]||href;
 if(u.pathname==='/calendar.ics')return 'index.html?route='+encodeURIComponent(u.pathname+u.search);
 if(!u.search&&PAGE_FILES[u.pathname])return PAGE_FILES[u.pathname]+u.hash;
 return 'index.html?route='+encodeURIComponent(u.pathname+u.search)+u.hash;
}
