 html=html.replace(/<form\b([^>]*)>/g,(m,a)=>{if(/id="note-form"/.test(a))return m;const action=a.match(/action="([^"]*)"/)?.[1]||new URL(route,'https://demo.invalid').pathname;return '<form'+a.replace(/\saction="[^"]*"/,'')+' data-demo-action="'+action+'">'});
